let ARB_BIG_TR_MAP = null
function arbBigTr(ar) {
  if (!ARB_BIG_TR_MAP) {
    ARB_BIG_TR_MAP = new Map()
    ARB_BIG_TR.split('\n').forEach(line => {
      const [w, tg, ru] = line.split('|')
      if (w) ARB_BIG_TR_MAP.set(arbKey(w), [tg || '', ru || ''])
    })
  }
  return ARB_BIG_TR_MAP.get(arbKey(ar)) || ['', '']
}

let ARB_DICT_TOTALS = null
function arbDictTotals() {
  if (!ARB_DICT_TOTALS) {
    let verbs = 0
    try {
      MZ.lexiconRoots().forEach(root => { verbs += (MZ.attestedWazns(root) || []).length })
    } catch { /* ignore */ }
    ARB_DICT_TOTALS = { words: ARB_NOUNS.length + arbBigNouns().length + ARB_PARTICLES.length, verbs }
  }
  return ARB_DICT_TOTALS
}

function arbBigNouns() {
  if (ARB_BIG_CACHE) return ARB_BIG_CACHE
  const out = []
  ARB_BIG_NOUNS.split('\n').forEach(line => {
    const [ar, plural, gender, code, root] = line.split('|')
    if (!ar) return
    const t = ARB_BIG_TYPES[code] || ARB_BIG_TYPES.j
    const keys = [arbKey(ar).replace(/^ال/, '')]
    if (plural) keys.push(arbKey(plural).replace(/^ال/, ''))
    out.push({ ar, plural: plural || '', gender: gender || '', type: t[0], typeRu: t[1], root: root || '', keys })
  })
  ARB_BIG_CACHE = out
  return out
}

